const std = @import("std");

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const request_body =
        \\{"model":"deepseek/deepseek-v4-pro","messages":[{"role":"system","content":"You are a helpful assistant."},{"role":"user","content":"What is AI?"}]}
    ;

    var client = std.http.Client{ .allocator = allocator };
    defer client.deinit();

    const uri = try std.Uri.parse("");

    var header_buf: [4096]u8 = undefined;
    var req = try client.open(.POST, uri, .{
        .server_header_buffer = &header_buf,
        .extra_headers = &.{
            .{ .name = "Content-Type", .value = "application/json" },
            .{ .name = "Authorization", .value = "Bearer <Your API Key>" },
        },
    });
    defer req.deinit();

    req.transfer_encoding = .{ .content_length = request_body.len };
    try req.send();
    try req.writeAll(request_body);
    try req.finish();
    try req.wait();

    const response_body = try req.reader().readAllAlloc(allocator, 10 * 1024 * 1024);
    defer allocator.free(response_body);

    const parsed = try std.json.parseFromSlice(std.json.Value, allocator, response_body, .{});
    defer parsed.deinit();

    const root = parsed.value;
    const choices = root.object.get("choices") orelse {
        try std.io.getStdOut().writer().print("No choices in response\n", .{});
        return;
    };
    const first_choice = choices.array.items[0];
    const message = first_choice.object.get("message") orelse {
        try std.io.getStdOut().writer().print("No message in choice\n", .{});
        return;
    };
    const content = message.object.get("content") orelse {
        try std.io.getStdOut().writer().print("No content in message\n", .{});
        return;
    };

    const stdout = std.io.getStdOut().writer();
    try stdout.print("{s}\n", .{content.string});
}
